def rotate(text, key):
    """
    Rotate alphabetic characters in text by key positions (Caesar/ROT cipher).
    Non-alphabetic characters are left unchanged. Case is preserved.
    """
    if not isinstance(key, int):
        try:
            key = int(key)
        except Exception:
            raise TypeError("key must be an integer")

    k = key % 26
    if k == 0:
        return text

    result_chars = []
    for ch in text:
        o = ord(ch)
        if 97 <= o <= 122:  # 'a'..'z'
            base = 97
            result_chars.append(chr((o - base + k) % 26 + base))
        elif 65 <= o <= 90:  # 'A'..'Z'
            base = 65
            result_chars.append(chr((o - base + k) % 26 + base))
        else:
            result_chars.append(ch)

    return ''.join(result_chars)
